options.customCss:
/* LLM4MTL master configuration wizard.
   Presentation only. Every option stays the form's own native input plus its
   label, so the submitted values are exactly what n8n submits without this
   stylesheet; the card is the label, and the input is stretched over it. */

:root {
  --container-width: 720px;
}

.container {
  text-align: left;
}

.form-label {
  font-weight: 600;
}

/* radio and checkbox groups share this markup, so both become card grids. */
.multiselect {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 10px;
  margin-top: 6px;
}

.multiselect .multiselect-option {
  position: relative;
  display: block;
  padding-top: 0;
}

.multiselect .multiselect-option > input.multiselect-checkbox {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  min-width: 0;
  margin: 0;
  border: none;
  border-radius: 10px;
  background: none;
  opacity: 0;
  cursor: pointer;
  z-index: 1;
}

.multiselect .multiselect-option > label {
  display: block;
  height: 100%;
  padding: 14px 16px;
  border: 1px solid var(--color-input-border);
  border-radius: 10px;
  background-color: var(--color-card-bg);
  color: var(--color-label);
  font-weight: 500;
  line-height: 1.35;
  text-align: left;
  cursor: pointer;
}

.multiselect .multiselect-option > input.multiselect-checkbox:hover + label {
  border-color: var(--color-focus-border);
}

.multiselect .multiselect-option > input.multiselect-checkbox:checked + label {
  border-color: var(--color-submit-btn-bg);
  box-shadow: inset 0 0 0 1px var(--color-submit-btn-bg);
  color: var(--color-header);
}

/* Run mode is the decision every other screen depends on, so its three cards
   carry a one-line explanation of what the mode actually executes. */
.multiselect .multiselect-option > input[value='Semantic Tests Only'] + label::before {
  content: '🧪';
}
.multiselect .multiselect-option > input[value='Transformations Only'] + label::before {
  content: '⚙️';
}
.multiselect .multiselect-option > input[value='Full Pipeline'] + label::before {
  content: '🚀';
}
.multiselect .multiselect-option > input[value='Semantic Tests Only'] + label::before,
.multiselect .multiselect-option > input[value='Transformations Only'] + label::before,
.multiselect .multiselect-option > input[value='Full Pipeline'] + label::before {
  display: inline-block;
  margin-right: 6px;
}
.multiselect .multiselect-option > input[value='Semantic Tests Only'] + label::after {
  content: 'Generate and validate semantic tests';
}
.multiselect .multiselect-option > input[value='Transformations Only'] + label::after {
  content: 'Generate transformations and parse them';
}
.multiselect .multiselect-option > input[value='Full Pipeline'] + label::after {
  content: 'Both branches, semantic execution, diagnosis';
}
.multiselect .multiselect-option > input[value='Semantic Tests Only'] + label::after,
.multiselect .multiselect-option > input[value='Transformations Only'] + label::after,
.multiselect .multiselect-option > input[value='Full Pipeline'] + label::after {
  display: block;
  margin-top: 4px;
  color: var(--color-link);
  font-size: var(--font-size-link);
  font-weight: 400;
}

@media only screen and (max-width: 500px) {
  .multiselect {
    grid-template-columns: 1fr;
  }
}

parameters.jsCode:
// One configuration screen, so the whole configuration arrives as one item.
const form = $input.first().json;

const asList = (value) => {
  if (Array.isArray(value)) return value.map(String).map((item) => item.trim()).filter(Boolean);
  if (typeof value !== 'string') return [];
  return value.split(',').map((item) => item.trim()).filter(Boolean);
};

const providers = {
  OpenAI: {
    id: 'openai',
    nodeSuffix: 'OpenAI Chat Model',
    artifactModel: 'gpt-5',
  },
  Anthropic: {
    id: 'anthropic',
    nodeSuffix: 'Anthropic Chat Model',
    artifactModel: 'claude-sonnet-4',
  },
  'Google Gemini': {
    id: 'google',
    nodeSuffix: 'Google Gemini Chat Model',
    artifactModel: 'gemini-2-5-pro',
  },
};
const roleNodes = {
  transformation: 'Transformation Generation',
  semantic_test: 'Semantic Test Generation',
  source_diagnosis: 'Source Diagnosis',
  refinement: 'Refinement',
};
// The form picks a provider; the exact model and the credential stay in the
// built-in selector of the matching standard AI Model node on the canvas. That
// selector is the provider's own model list, so the master never carries one.
const selectedModel = (role, providerLabel) => {
  const provider = providers[providerLabel];
  if (!provider) throw new Error(`Select a supported provider for ${role}`);
  const nodeName = `${roleNodes[role]} - ${provider.nodeSuffix}`;
  const parameters = $(nodeName).params;
  const configuredModel = provider.id === 'google' ? parameters.modelName : parameters.model;
  const model = configuredModel && typeof configuredModel === 'object'
    ? configuredModel.value
    : configuredModel;
  if (typeof model !== 'string' || !model.trim()) {
    throw new Error(`Select a model in the built-in selector of ${nodeName}`);
  }
  return {
    provider: provider.id,
    model: model.trim(),
    artifact_model: provider.artifactModel,
    configuration_node: nodeName,
  };
};

// run_mode is the pipeline the user intends to execute. The stage flags below
// say which components of that pipeline are enabled; the two are separate axes
// and a run records both.
const runModes = {
  'Semantic Tests Only': 'tests_only',
  'Transformations Only': 'transformations_only',
  'Full Pipeline': 'full',
};
const runMode = runModes[form.run_mode];
if (!runMode) throw new Error('Select a supported run mode');
const runsTests = runMode !== 'transformations_only';
const runsTransformations = runMode !== 'tests_only';

const languageOptions = {
  ETL: 'etl',
  ATL: 'atl',
  'QVT-O': 'qvto',
  Reactions: 'reactions',
};
const languages = [...new Set(asList(form.languages).map((label) => languageOptions[label]))];
if (languages.length === 0 || languages.some((language) => !language)) {
  throw new Error('Select at least one supported language');
}

// Task names come from benchmark/tasks/<language>/task_contracts, which the form
// lists. A second copy of that list here would be the thing that goes stale, so
// the master checks the shape and lets POST /runs refuse a task whose contract
// does not exist.
const taskFields = {
  etl: 'etl_tasks',
  atl: 'atl_tasks',
  qvto: 'qvto_tasks',
  reactions: 'reactions_tasks',
};
const tasksByLanguage = {};
for (const language of languages) {
  const tasks = asList(form[taskFields[language]]);
  if (tasks.length === 0) {
    throw new Error(`Select at least one task for ${language}`);
  }
  for (const task of tasks) {
    if (!/^[A-Za-z0-9._-]+$/.test(task)) {
      throw new Error(`Unsupported task name for ${language}: ${task}`);
    }
  }
  tasksByLanguage[language] = tasks;
}

const stageFields = [
  'test_generation',
  'test_extraction',
  'technical_validation',
  'reference_validation',
  'transformation_generation',
  'syntax_validation',
  'semantic_execution',
  'source_diagnosis',
  'parser_feedback',
  'semantic_feedback',
  'test_refinement',
  'transformation_refinement',
];
// The named profiles are the RQ4 variants the repository already defines in
// experiments/variants/. Custom ablation is the escape hatch that can express
// any of the twelve components.
const ablationProfiles = {
  'Standard full configuration': { id: 'full', disabled: [] },
  'No parser feedback': { id: 'no-parser-feedback', disabled: ['parser_feedback'] },
  'No semantic feedback': { id: 'no-semantic-feedback', disabled: ['semantic_feedback'] },
  'No failure diagnosis': { id: 'no-failure-diagnosis', disabled: ['source_diagnosis'] },
};
const profileLabel = form.ablation_profile;
const customComponents = asList(form.disabled_components);
let disabledStages;
let ablationId;
if (profileLabel === 'Custom ablation') {
  for (const component of customComponents) {
    if (!stageFields.includes(component)) {
      throw new Error(`Unknown pipeline component: ${component}`);
    }
  }
  disabledStages = stageFields.filter((stage) => customComponents.includes(stage));
  ablationId = disabledStages.length === 0 ? 'full' : `custom:${disabledStages.join('+')}`;
} else if (ablationProfiles[profileLabel]) {
  // A named profile fixes its disabled set. Honouring an extra selection here
  // would run an ablation the recorded variant id does not name.
  if (customComponents.length > 0) {
    throw new Error('Select "Custom ablation" to disable individual components');
  }
  disabledStages = ablationProfiles[profileLabel].disabled;
  ablationId = ablationProfiles[profileLabel].id;
} else {
  throw new Error('Select a supported experiment configuration');
}
const stages = {};
for (const stage of stageFields) {
  stages[stage] = !disabledStages.includes(stage);
}

const refinementOptions = [0, 1, 2, 3];
const maxTestRefinementIterations = Number(form.max_test_refinement_iterations);
const maxTransformationRefinementIterations = Number(form.max_transformation_refinement_iterations);
if (!refinementOptions.includes(maxTestRefinementIterations)) {
  throw new Error('Test refinement iterations must be selected from 0 through 3');
}
if (!refinementOptions.includes(maxTransformationRefinementIterations)) {
  throw new Error('Transformation refinement iterations must be selected from 0 through 3');
}

// The card shows the reading name; the run records the canonical strategy id,
// which is what the variant workflows are named after and what the manifest and
// the prompting-strategy axis carry.
const strategyIds = {
  'Prompt only': 'only_prompt',
  'Few-shot': 'few_shot',
  Grammar: 'grammar',
  'Few-shot + Grammar': 'few_shots_AND_grammar',
};

// Reachability follows from the final configuration: the run mode decides which
// branches exist, the stage flags decide which of their components run. A role
// nothing can call is left unconfigured rather than demanded from the user.
const reachable = {
  semantic_test: runsTests && stages.test_generation,
  transformation: runsTransformations && stages.transformation_generation,
  source_diagnosis: runMode === 'full' && stages.semantic_execution && stages.semantic_feedback && stages.source_diagnosis,
  refinement: (
    (maxTestRefinementIterations > 0 && runsTests && stages.test_generation && stages.test_refinement)
    || (maxTransformationRefinementIterations > 0 && runsTransformations && stages.transformation_generation && stages.transformation_refinement)
  ),
};

const llms = {};
if (reachable.semantic_test) {
  const strategy = strategyIds[form.semantic_test_strategy];
  if (!strategy) throw new Error('Select a supported Semantic Test Generation strategy');
  llms.semantic_test = {
    ...selectedModel('semantic_test', form.semantic_test_provider),
    strategy,
  };
}
if (reachable.transformation) {
  const strategy = strategyIds[form.transformation_strategy];
  if (!strategy) throw new Error('Select a supported Transformation Generation strategy');
  llms.transformation = {
    ...selectedModel('transformation', form.transformation_provider),
    strategy,
  };
}
if (reachable.source_diagnosis) {
  llms.source_diagnosis = selectedModel('source_diagnosis', form.source_diagnosis_provider);
}
if (reachable.refinement) {
  llms.refinement = selectedModel('refinement', form.refinement_provider);
}

const root = String(form.n8n_workflow_root || '/data/repository/workflows/n8n').replace(/\/$/, '');
if (!root.startsWith('/data/') || root.includes('..')) {
  throw new Error('Workflow root must be a contained read-only mount below /data');
}

// The variant identifies both axes: which pipeline ran and which components were
// ablated. A standard full run keeps the plain 'full' id earlier runs recorded.
const pipelineVariant = ablationId === 'full' ? runMode : `${runMode}:${ablationId}`;
const labels = {
  etl: 'ETL',
  atl: 'ATL',
  qvto: 'QVTO',
  reactions: 'Reactions',
};

const runSpecs = [];
for (const language of languages) {
  const label = labels[language];
  for (const task of tasksByLanguage[language]) {
    const transformationWorkflow = !llms.transformation
      ? null
      : language === 'reactions'
        ? `${root}/transformations/workflows/updated_reactions_workflow/generate_reactions/LLM4MTL_Generate_Reactions_for_all_Configurations.json`
        : `${root}/transformations/workflows/${language}_variants/Prompting_${label}_*_${llms.transformation.strategy}.json`;
    runSpecs.push({
      language,
      language_label: label,
      task,
      run_mode: runMode,
      // Python selects artifacts by the stable family directory. The exact
      // provider model remains in config.llms and is passed only to n8n LLM nodes.
      transformation_model: llms.transformation ? llms.transformation.artifact_model : null,
      test_generation_model: llms.semantic_test ? llms.semantic_test.artifact_model : null,
      transformation_strategy: llms.transformation ? llms.transformation.strategy : null,
      test_generation_strategy: llms.semantic_test ? llms.semantic_test.strategy : null,
      seed: 1,
      pipeline_variant: pipelineVariant,
      test_generation_workflow: llms.semantic_test
        ? `${root}/tests/workflows/${language}_variants/test_generation/Prompting_tests_${label}_*_${llms.semantic_test.strategy}.json`
        : null,
      transformation_generation_workflow: transformationWorkflow,
      diagnosis_workflow: llms.source_diagnosis
        ? `${root}/subworkflows/diagnosis/llm-diagnosis.json`
        : null,
    });
  }
}

return [{
  json: {
    config: {
      run_mode: runMode,
      llms,
      max_test_refinement_iterations: maxTestRefinementIterations,
      max_transformation_refinement_iterations: maxTransformationRefinementIterations,
      stages,
      ablation_profile: ablationId,
      disabled_stages: disabledStages,
      pipeline_variant: pipelineVariant,
    },
    run_specs: runSpecs,
    run_index: 0,
    current: {
      ...runSpecs[0],
      run_id: null,
      suite_id: null,
      test_iteration: 0,
      transformation_iteration: 0,
      generation_purpose: 'initial',
      has_transformation: false,
      timeline: [],
      terminal_status: null,
      terminal_reason: null,
    },
    results: [],
    action: null,
    completed_action: null,
    last_result: null,
  },
}];

// The Code node runs in a bare VM context, which has the JavaScript
// built-ins but none of Node's host globals: structuredClone is not one of
// them. The state is pure JSON, so a JSON round trip is a faithful clone.
const state = JSON.parse(JSON.stringify($input.first().json));
const flags = state.config.stages;
const maxRefinements = {
  tests: state.config.max_test_refinement_iterations,
  transformations: state.config.max_transformation_refinement_iterations,
};

// run_mode is which pipeline the user asked for; the stage flags are which of
// its components are enabled. A mode never reaches a stage of the other branch,
// however the flags are set, so the two stay separable in the recorded config.
const runMode = state.config.run_mode;
const modeStages = {
  tests_only: ['generate_tests', 'extract', 'technical', 'reference'],
  transformations_only: ['generate_transformations', 'syntax'],
  full: ['generate_tests', 'extract', 'technical', 'reference', 'generate_transformations', 'syntax', 'execution'],
};
if (!modeStages[runMode]) throw new Error(`Unknown run mode: ${runMode}`);
const modeAllows = (action) => (['diagnose', 'read_diagnosis_index'].includes(action)
  ? runMode === 'full'
  : modeStages[runMode].includes(action));

const actionFlag = {
  generate_tests: 'test_generation',
  extract: 'test_extraction',
  technical: 'technical_validation',
  reference: 'reference_validation',
  generate_transformations: 'transformation_generation',
  syntax: 'syntax_validation',
  execution: 'semantic_execution',
  diagnose: 'source_diagnosis',
};
const stageIds = {
  extract: 'extract',
  technical: 'technical-validation',
  reference: 'reference-validation',
  syntax: 'syntax-validation',
  execution: 'execution',
};

function choose(action) {
  state.action = action;
  state.stage_id = stageIds[action] || null;
  state.subworkflow_path = null;
  state.subworkflow_input = null;
  state.stage_iteration = ['extract', 'technical', 'reference'].includes(action)
    ? state.current.test_iteration
    : ['syntax', 'execution'].includes(action)
      ? state.current.transformation_iteration
      : null;
  if (action === 'generate_tests') {
    state.subworkflow_path = state.current.test_generation_workflow;
    state.subworkflow_input = {
      language: state.current.language,
      task: state.current.task,
      provider: (state.current.test_iteration > 0 ? state.config.llms.refinement : state.config.llms.semantic_test).provider,
      model: (state.current.test_iteration > 0 ? state.config.llms.refinement : state.config.llms.semantic_test).model,
      strategy: state.config.llms.semantic_test.strategy,
      llm_role: state.current.test_iteration > 0 ? 'refinement' : 'semantic_test',
      run_id: state.current.run_id,
      refinement_iteration: state.current.test_iteration,
      refinement_reason: state.current.refinement_reason || null,
      prompt_path: state.current.test_iteration > 0 ? state.current.refinement_prompt_path : null,
    };
  } else if (action === 'generate_transformations') {
    state.subworkflow_path = state.current.transformation_generation_workflow;
    state.subworkflow_input = {
      language: state.current.language,
      task: state.current.task,
      provider: (state.current.transformation_iteration > 0 ? state.config.llms.refinement : state.config.llms.transformation).provider,
      model: (state.current.transformation_iteration > 0 ? state.config.llms.refinement : state.config.llms.transformation).model,
      strategy: state.config.llms.transformation.strategy,
      llm_role: state.current.transformation_iteration > 0 ? 'refinement' : 'transformation',
      run_id: state.current.run_id,
      refinement_iteration: state.current.transformation_iteration,
      refinement_reason: state.current.refinement_reason || null,
      prompt_path: state.current.transformation_iteration > 0 ? state.current.refinement_prompt_path : null,
    };
  } else if (action === 'prepare_refinement') {
    state.refinement_request = {
      artifact_type: state.current.refinement_target === 'tests' ? 'semantic-test' : 'transformation',
      iteration: state.current.refinement_target === 'tests' ? state.current.test_iteration : state.current.transformation_iteration,
      previous_iteration: state.current.previous_artifact_iteration,
      provider: state.config.llms.refinement.provider,
      model: state.config.llms.refinement.model,
      reason: state.current.refinement_reason,
      execution_attempt: (state.current.refinement_reason || '').startsWith('DIAGNOSED_') || (state.current.refinement_reason || '').startsWith('SEMANTIC_')
        ? state.current.execution_result?.attempt || null
        : null,
    };
  } else if (action === 'record_generation') {
    state.generation_record = state.current.pending_generation;
  } else if (action === 'read_diagnosis_index') {
    // Python names artifacts by repository path; the run's artifacts are mounted
    // into this container at /data/artifacts. The report paths inside the index
    // stay repository-relative, because the diagnosis subworkflow does its own
    // containment check on them.
    const indexPath = String(state.current.diagnosis_index_path || '').replace(/\\/g, '/');
    const runPrefix = `artifacts/work/runs/${state.current.run_id}/`;
    if (!indexPath.startsWith(runPrefix) || indexPath.includes('..')) {
      throw new Error(`Diagnosis index must identify this run under artifacts/work: ${indexPath}`);
    }
    state.diagnosis_execution_attempt = state.current.execution_result.attempt;
  } else if (action === 'diagnose') {
    // One report per invocation. The queue was built from the attempt's index,
    // so which failures get diagnosed is the recorded set, not the first of them.
    const pending = state.current.diagnosis_queue[state.current.diagnosis_cursor];
    state.subworkflow_path = state.current.diagnosis_workflow;
    state.subworkflow_input = {
      run_id: state.current.run_id,
      outcome_code: 'SEMANTIC_EXECUTION_FAILED',
      execution_attempt: state.current.execution_result.attempt,
      diagnosis_provider: state.config.llms.source_diagnosis.provider,
      model: state.config.llms.source_diagnosis.model,
      llm_role: 'source_diagnosis',
      failure_report_path: pending.failure_report_path,
    };
  }
}

function finish(status, reason) {
  state.current.terminal_status = status;
  state.current.terminal_reason = reason;
  choose('final');
}

function nextEnabled(actions, emptyReason) {
  for (const action of actions) {
    if (modeAllows(action) && flags[actionFlag[action]]) {
      choose(action);
      return;
    }
  }
  // Nothing left here belongs to this mode's pipeline, and the pipeline did run:
  // that is the mode's own successful terminal point, not an unfinished run. A
  // stage that is merely ablated keeps the existing incomplete reason, because
  // that configuration stopped short of the end it asked for.
  if (state.current.timeline.length > 0 && !actions.some(modeAllows)) {
    finish('completed', `${runMode.toUpperCase()}_PIPELINE_COMPLETE`);
    return;
  }
  finish('incomplete', emptyReason);
}

function afterTestArtifact() {
  nextEnabled(
    ['extract', 'technical', 'reference', 'generate_transformations', 'syntax', 'execution'],
    'NO_POST_TEST_GENERATION_STAGE_ENABLED',
  );
}

function afterValidatedTests() {
  if (state.current.has_transformation) {
    // A test refinement does not mutate the already syntax-valid transformation.
    nextEnabled(['execution'], 'SEMANTIC_EXECUTION_DISABLED');
    return;
  }
  nextEnabled(
    ['generate_transformations', 'syntax', 'execution'],
    'NO_TRANSFORMATION_STAGE_ENABLED',
  );
}

function refinementSource(reason) {
  const sourceByReason = {
    TEST_SPEC_INVALID: 'technical',
    TECH_COMPILE_FAILED: 'technical',
    TECH_EXEC_FAILED: 'technical',
    REFERENCE_VALIDATION_FAILED: 'reference',
    SYNTAX_INVALID: 'syntax',
    SEMANTIC_EXECUTION_FAILED_WITHOUT_DIAGNOSIS: 'semantic',
    DIAGNOSED_TRANSFORMATION_DEFECT: 'semantic',
    DIAGNOSED_TEST_DEFECT: 'semantic',
  };
  const source = sourceByReason[reason];
  if (!source) throw new Error(`Unknown refinement reason: ${reason}`);
  return source;
}

function refinementPurpose(target, source, iteration) {
  if (iteration === 0) return 'initial';
  const purposes = {
    tests: {
      technical: 'technical_refinement',
      reference: 'reference_refinement',
      semantic: 'semantic_refinement',
    },
    transformations: {
      syntax: 'syntax_refinement',
      semantic: 'semantic_refinement',
    },
  };
  const purpose = purposes[target]?.[source];
  if (!purpose) throw new Error(`Unsupported ${target} refinement source: ${source}`);
  return purpose;
}

function requestRefinement(target, reason) {
  if (!['tests', 'transformations'].includes(target)) {
    throw new Error(`Unknown refinement target: ${target}`);
  }
  const source = refinementSource(reason);
  const targetAction = target === 'tests' ? 'generate_tests' : 'generate_transformations';
  if (!modeAllows(targetAction)) {
    finish('completed_with_failures', `${reason}:OUT_OF_RUN_MODE_SCOPE`);
    return;
  }
  const refinementFlag = target === 'tests' ? flags.test_refinement : flags.transformation_refinement;
  const generationFlag = target === 'tests' ? flags.test_generation : flags.transformation_generation;
  if (!refinementFlag || !generationFlag) {
    finish('completed_with_failures', `${reason}:REFINEMENT_DISABLED`);
    return;
  }
  if (!state.config.llms.refinement) {
    finish('completed_with_failures', `${reason}:REFINEMENT_MODEL_NOT_CONFIGURED`);
    return;
  }
  const iterationsUsed = target === 'tests'
    ? state.current.test_iteration
    : state.current.transformation_iteration;
  if (iterationsUsed >= maxRefinements[target]) {
    finish('completed_with_failures', `${reason}:REFINEMENT_LIMIT_REACHED`);
    return;
  }
  state.current.refinement_target = target;
  state.current.refinement_source = source;
  state.current.previous_artifact_iteration = target === 'tests'
    ? state.current.test_iteration
    : state.current.transformation_iteration;
  if (target === 'tests') {
    state.current.test_iteration += 1;
    // A refined suite is a new suite and gets its own id. A refined
    // transformation is judged against the suite that was already validated
    // against the reference - renaming it here left the execution stage
    // selecting a suite that does not exist, and every transformation
    // refinement ended in an infrastructure error instead of an execution.
    state.current.suite_id = `${state.current.run_id}_${String(state.current.test_iteration).padStart(3, '0')}`;
  } else {
    state.current.transformation_iteration += 1;
  }
  state.current.refinement_reason = reason;
  state.current.generation_purpose = `${target}_refinement`;
  choose('prepare_refinement');
}

function recordStage(action, result) {
  state.current.timeline.push({
    action,
    stage: result.stage || null,
