    const assembler = workflow.nodes.find((node) => node.name === 'Assemble prompt');
    const assembledPrompt = assembler?.parameters?.assignments?.assignments?.find((assignment) => assignment.name === 'assembled_prompt');
    if (!assembledPrompt) throw new Error('Semantic-test workflow has no assembled_prompt assignment');
    assembledPrompt.value = '={{ $json.prompt }}';
  }
} else {
  promptReader.parameters.fileSelector = `=/data/task_prompts/${language}/${task}.txt`;
}

const operation = state.action === 'generate_tests'
  ? 'semantic-test-generation'
  : 'transformation-generation';
const extensions = { etl: 'etl', atl: 'atl', qvto: 'qvto', reactions: 'reactions' };
const extension = state.action === 'generate_tests' ? 'md' : extensions[language];
if (!extension) throw new Error(`No generated transformation extension for ${language}`);
const iterationName = String(iteration).padStart(3, '0');
const responseDirectory = `/data/artifacts/runs/${runId}/responses/${operation}/iteration-${iterationName}`;
const responseWriter = workflow.nodes.find((node) => node.name === 'Write response to disk');
if (!responseWriter || responseWriter.type !== 'n8n-nodes-base.readWriteFile') {
  throw new Error('Generation workflow has no supported response writer');
}
responseWriter.parameters.fileName = `=${responseDirectory}/${task}.${extension}`;

// Semantic-test workflows already archive the assembled request. Keep it next
// to the run-scoped response so the response is attributable after a later run
// overwrites the shared convenience tree.
if (state.action === 'generate_tests') {
  const promptWriter = workflow.nodes.find((node) => node.name === 'Write prompt to disk');
  if (promptWriter && promptWriter.type === 'n8n-nodes-base.readWriteFile') {
    promptWriter.parameters.fileName = `=${responseDirectory}/prompt.md`;
  }
}

if (state.action === 'generate_transformations') {
  // Legacy transformation workflows were authored before Set v3.4 stripped
  // binary data by default. Their next Extract From File node still consumes
  // binary.data, so preserve it only in this invocation-local compatibility copy.
  const saveName = saveFileName;
  saveName.parameters.options = { ...(saveName.parameters.options || {}) };
  if (Number(saveName.typeVersion || 0) >= 3.4) {
    saveName.parameters.includeOtherFields = true;
    saveName.parameters.options.stripBinary = false;
  } else {
    saveName.parameters.options.includeBinary = true;
  }
}

return [input];

const state = $('State Machine').first().json;
const items = $input.all();
const lastResult = items.length === 1
  ? items[0].json
  : { items: items.map((item) => item.json) };
return [{
  json: {
    ...state,
    completed_action: state.action,
    last_result: lastResult,
  },
}];

const state = $input.first().json;
if (!state.config || !Array.isArray(state.results)) {
  throw new Error('Final result requires normalized workflow state with config and results');
}
const statuses = state.results.map((result) => result.status);
const status = statuses.includes('failed')
  ? 'failed'
  : statuses.includes('completed_with_failures')
    ? 'completed_with_failures'
    : statuses.includes('incomplete')
      ? 'incomplete'
      : 'completed';
return [{
  json: {
    status,
    run_mode: state.config.run_mode,
    run_count: state.results.length,
    languages: state.results.map((result) => result.language),
    pipeline_variant: state.config.pipeline_variant,
    results: state.results,
  },
}];

const incoming = $input.first().json || {};
let source = incoming;
try {
  const machine = $('State Machine').first().json;
  if (!source?.current?.run_id && machine?.current?.run_id) source = machine;
} catch (error) {
  // The failing State Machine has no successful output; its input still carries the run.
}
const state = JSON.parse(JSON.stringify(source));
if (!state.current?.run_id) {
  throw new Error('Cannot terminalize orchestration failure before a run was created');
}
const failedComponent = String(state.action || incoming.error?.node?.name || 'unknown-orchestration-component');
const lastStage = [...(state.current.timeline || [])].reverse().find((entry) => entry.stage)?.stage || null;
state.current.terminal_status = 'failed';
state.current.terminal_reason = `ORCHESTRATION_ERROR:${failedComponent}`;
state.orchestration_terminal_request = {
  status: 'failed',
  terminal_state: state.current.terminal_reason,
  run_mode: state.config.run_mode,
  refinement_iterations_used: (state.current.test_iteration || 0) + (state.current.transformation_iteration || 0),
  refinement_iterations_allowed: (state.config.run_mode === 'transformations_only' ? 0 : state.config.max_test_refinement_iterations)
    + (state.config.run_mode === 'tests_only' ? 0 : state.config.max_transformation_refinement_iterations),
  suite_id: state.current.suite_id || null,
  failed_component: failedComponent,
  last_completed_stage: lastStage,
  test_iteration: state.current.test_iteration || 0,
  transformation_iteration: state.current.transformation_iteration || 0,
};
return [{json: state}];

const terminal = $input.first().json;
const state = JSON.parse(JSON.stringify($('Capture Orchestration Error').first().json));
const completedResults = Array.isArray(state.results) ? state.results : [];
const failedResult = {
  run_id: terminal.run_id || state.current.run_id,
  language: state.current.language,
  task: state.current.task,
  status: 'failed',
  reason: terminal.terminal_state || state.current.terminal_reason,
  failed_component: terminal.failed_component,
  last_completed_stage: terminal.last_completed_stage,
  test_iteration: terminal.test_iteration,
  transformation_iteration: terminal.transformation_iteration,
  artifacts: terminal,
};
state.results = [...completedResults, failedResult];
return [{json: state}];
